  `folder` varchar(255) DEFAULT 'none',
  `schedule` varchar(50) DEFAULT 'weekly',
  `user_agent` varchar(100) DEFAULT 'seox-desktop',
  `url_limit` bigint DEFAULT '10000',
  `total_urls` bigint DEFAULT '0',
